// SetStateSnapshotNidEvents removes all previously related items of the
// state_snapshot replacing them completely with the passed
// in related items, optionally inserting them as new records.
// Sets o.R.StateSnapshotNidStateSnapshot's StateSnapshotNidEvents accordingly.
// Replaces o.R.StateSnapshotNidEvents with related.
// Sets related.R.StateSnapshotNidStateSnapshot's StateSnapshotNidEvents accordingly.
func (o *StateSnapshot) SetStateSnapshotNidEvents(ctx context.Context, exec boil.ContextExecutor, insert bool, related ...*Event) error {
	query := "update \"events\" set \"state_snapshot_nid\" = null where \"state_snapshot_nid\" = $1"
	values := []any{o.StateSnapshotNid}
	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, query)
		fmt.Fprintln(writer, values)
	}
	_, err := exec.ExecContext(ctx, query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}

	if o.R != nil {
		for _, rel := range o.R.StateSnapshotNidEvents {
			queries.SetScanner(&rel.StateSnapshotNid, nil)
			if rel.R == nil {
				continue
			}

			rel.R.StateSnapshotNidStateSnapshot = nil
		}
		o.R.StateSnapshotNidEvents = nil
	}

	return o.AddStateSnapshotNidEvents(ctx, exec, insert, related...)
}

// RemoveStateSnapshotNidEvents relationships from objects passed in.
// Removes related items from R.StateSnapshotNidEvents (uses pointer comparison, removal does not keep order)
// Sets related.R.StateSnapshotNidStateSnapshot.
func (o *StateSnapshot) RemoveStateSnapshotNidEvents(ctx context.Context, exec boil.ContextExecutor, related ...*Event) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	for _, rel := range related {
		queries.SetScanner(&rel.StateSnapshotNid, nil)
		if rel.R != nil {
			rel.R.StateSnapshotNidStateSnapshot = nil
		}
		if _, err = rel.Update(ctx, exec, boil.Whitelist("state_snapshot_nid")); err != nil {
			return err
		}
	}
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.StateSnapshotNidEvents {
			if rel != ri {
				continue
			}

			ln := len(o.R.StateSnapshotNidEvents)
			if ln > 1 && i < ln-1 {
				o.R.StateSnapshotNidEvents[i] = o.R.StateSnapshotNidEvents[ln-1]
			}
			o.R.StateSnapshotNidEvents = o.R.StateSnapshotNidEvents[:ln-1]
			break
		}
	}

	return nil
}

